<?php

declare(strict_types=1);

namespace App\Actions\Payment;

use App\Domain\Order\Models\Order;
use App\Actions\Coupon\ManageCouponUsageAction;
use App\Domain\Payment\Enums\PaymentStatus;
use App\Domain\Payment\Models\Payment;
use App\Domain\Payment\Models\PaymentIntegration;
use App\Infrastructure\Payments\AsaasGateway;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Http;
use Illuminate\Support\Facades\Log;
use Illuminate\Validation\ValidationException;

/**
 * Authoritative, read-only lookup of the payments generated by a hosted Asaas
 * checkout. Never infer success or expiration from a browser redirect or timer.
 */
final class ReconcileAsaasPaymentAction
{
    public function execute(Payment $payment): void
    {
        if ($payment->gateway !== 'asaas' || $payment->status !== PaymentStatus::PENDING) {
            return;
        }

        if (str_starts_with($payment->external_id, 'initiating-')) {
            $this->flag($payment, 'Criação Asaas inconclusiva: conferir checkout no painel Asaas.');
            return;
        }

        $integration = PaymentIntegration::query()->find($payment->payment_integration_id);
        if ($integration === null || $integration->provider !== 'asaas' || $integration->environment !== $payment->environment || $integration->accessToken() === '') {
            $this->flag($payment, 'Integração Asaas do pagamento não está disponível para conciliação.');
            return;
        }

        $base = $integration->environment === 'production' ? 'https://api.asaas.com/v3' : 'https://api-sandbox.asaas.com/v3';
        $response = Http::baseUrl($base)->acceptJson()->withHeaders([
            'access_token' => $integration->accessToken(),
            'User-Agent' => 'SabaEcommerce/1.0 (payment-reconciliation)',
        ])->connectTimeout(5)->timeout(15)->get('/payments', [
            'checkoutSession' => $payment->external_id,
            'limit' => 100,
        ]);

        if (! $response->successful()) {
            Log::warning('Asaas payment reconciliation request failed.', [
                'payment_id' => $payment->id, 'http_status' => $response->status(),
            ]);
            $payment->update(['last_checked_at' => now()]);
            return; // Keep reservation. Never guess status on API failure.
        }

        $body = $response->json();
        if (! is_array($body) || ! is_array($body['data'] ?? null)) {
            Log::warning('Asaas payment reconciliation returned unexpected response.', ['payment_id' => $payment->id]);
            $payment->update(['last_checked_at' => now()]);
            return;
        }

        $rows = $body['data'];
        if (($body['hasMore'] ?? false) === true || count($rows) > 1) {
            $this->flag($payment, 'Múltiplas cobranças vinculadas ao checkout Asaas: conferência financeira necessária.');
            return; // Installments/multiple transactions require separate validation.
        }

        if ($rows === []) {
            $payment->update(['last_checked_at' => now()]);
            return;
        }

        $row = $rows[0];
        if (! is_array($row)) {
            $this->flag($payment, 'Resposta de conciliação Asaas inválida.');
            return;
        }

        $checkout = $row['checkoutSession'] ?? null;
        if ($checkout !== null && $checkout !== $payment->external_id) {
            $this->flag($payment, 'Checkout da cobrança retornada diverge do pedido.');
            return;
        }

        $order = $payment->order;
        $reference = $row['externalReference'] ?? null;
        if ($order === null || ($reference !== null && $reference !== $order->number)) {
            $this->flag($payment, 'Referência financeira do Asaas diverge do pedido.');
            return;
        }

        $value = $row['value'] ?? null;
        $rawValue = is_string($value) ? $value : (is_int($value) || is_float($value) ? json_encode($value, JSON_PRESERVE_ZERO_FRACTION) : null);
        $amount = is_string($rawValue) ? AsaasGateway::cents($rawValue) : null;
        if ($amount === null || $amount !== $payment->amount_cents || $order->total_cents !== $payment->amount_cents) {
            $this->flag($payment, 'Valor da cobrança Asaas diverge do pedido; não aprovar automaticamente.');
            return;
        }

        $status = $row['status'] ?? null;
        if (! in_array($status, ['CONFIRMED', 'RECEIVED'], true)) {
            if (in_array($status, ['REFUNDED', 'CHARGEBACK_REQUESTED', 'CHARGEBACK_DISPUTE'], true)) {
                $this->flag($payment, 'Estorno ou contestação no Asaas: conferir pedido manualmente.');
                return;
            }
            $payment->update(['provider_status' => is_string($status) ? $status : null, 'last_checked_at' => now()]);
            return;
        }

        DB::transaction(function () use ($payment, $order, $status): void {
            $lockedOrder = Order::query()->lockForUpdate()->findOrFail($order->id);
            $lockedPayment = Payment::query()->lockForUpdate()->findOrFail($payment->id);
            if ($lockedPayment->status !== PaymentStatus::PENDING) {
                return;
            }
            if ($lockedOrder->payments()->whereKeyNot($lockedPayment->id)->where('status', PaymentStatus::APPROVED->value)->exists()) {
                $this->flag($lockedPayment, 'Pagamento adicional identificado: conferência de estorno necessária.');
                return;
            }
            try {
                // Nested transaction savepoint protects against partial stock consumption.
                DB::transaction(fn () => app(HandleApprovedPaymentAction::class)->execute($lockedOrder, $lockedPayment));
                $lockedPayment->update(['provider_status' => $status, 'last_checked_at' => now()]);
                Log::info('Asaas payment reconciled as approved.', ['order_id' => $lockedOrder->id, 'payment_id' => $lockedPayment->id]);
            } catch (ValidationException $exception) {
                $lockedPayment->update(['status' => PaymentStatus::APPROVED, 'provider_status' => $status, 'last_checked_at' => now()]);
                $lockedOrder->update(['payment_status' => PaymentStatus::APPROVED]);
                app(ManageCouponUsageAction::class)->consume($lockedOrder);
                $this->flag($lockedPayment, 'Cobrança confirmada, mas pedido/estoque exige intervenção manual.');
            }
        }, 3);
    }

    private function flag(Payment $payment, string $message): void
    {
        $payment->update(['needs_review' => true, 'review_reason' => $message, 'last_checked_at' => now()]);
        Log::warning('Asaas payment requires manual review.', ['payment_id' => $payment->id, 'reason' => $message]);
    }
}
